// ===== Correction historique admin =====
function saveQuizHistory(entry) {
    try {
        const oldData = JSON.parse(localStorage.getItem('quiz_history') || '[]');
        oldData.unshift(entry);
        localStorage.setItem('quiz_history', JSON.stringify(oldData));

        if (typeof renderAdminHistory === 'function') {
            renderAdminHistory();
        }
    } catch(e) {
        console.error(e);
    }
}

function renderAdminHistory() {
    const historyContainer = document.getElementById('admin-history-list');
    if (!historyContainer) return;

    const data = JSON.parse(localStorage.getItem('quiz_history') || '[]');

    historyContainer.innerHTML = '';

    if (!data.length) {
        historyContainer.innerHTML = '<p>Aucun historique disponible</p>';
        return;
    }

    data.forEach(item => {
        const div = document.createElement('div');
        div.className = 'history-item';
        div.innerHTML = `
            <strong>${item.nom || 'Étudiant'}</strong><br>
            Score : ${item.score || 0}<br>
            Date : ${item.date || new Date().toLocaleString()}
            <hr>
        `;
        historyContainer.appendChild(div);
    });
}

document.addEventListener('DOMContentLoaded', () => {
    setTimeout(() => {
        if (typeof renderAdminHistory === 'function') {
            renderAdminHistory();
        }
    }, 500);
});
// ===== FIN : assets/js/core/firebase-config.js =====

// ===== DEBUT : assets/js/core/database.js =====
// Base de donnees Firebase Firestore pour sauvegarder les resultats, connexions et sessions en ligne.
// Si Firebase n'est pas encore configure, le site continue avec localStorage.

(function () {
  const missingConfig = !window.FIREBASE_CONFIG ||
    Object.values(window.FIREBASE_CONFIG).some((value) => String(value || "").startsWith("REMPLACE"));

  window.quizDB = {
    isReady: false,
    async saveResult() { return false; },
    async getLeaderboard() { return []; },
    async getStudentHistory() { return []; },
    async getAllResults() { return []; },
    async saveConnection() { return false; },
    async getConnections() { return []; },
    async acquireSessionLock() { return { ok: true, offline: true }; },
    async releaseSessionLock() { return true; },
    async createStudent() { return false; },
    async getStudents() { return []; },
    async getStudentByCode() { return null; },
    async clearAllData() { return false; }
  };

  if (missingConfig) {
    console.warn("Firebase non configure : utilisation du stockage local uniquement.");
    return;
  }

  // Hors connexion, toutes les fonctions principales continuent avec localStorage.
  // Firebase est facultatif et n'est chargé que lorsqu'une connexion est disponible.
  if (!navigator.onLine) {
    console.info("Mode hors connexion actif : stockage local uniquement.");
    return;
  }

  const script = document.createElement("script");
  script.type = "module";
  script.textContent = `
    import { initializeApp } from "https://www.gstatic.com/firebasejs/10.12.2/firebase-app.js";
    import {
      getFirestore, collection, addDoc, getDocs, query, orderBy, limit, where,
      serverTimestamp, doc, runTransaction, deleteDoc, setDoc, getDoc
    } from "https://www.gstatic.com/firebasejs/10.12.2/firebase-firestore.js";

    const app = initializeApp(window.FIREBASE_CONFIG);
    const db = getFirestore(app);
    const SESSION_TIMEOUT_MS = 2 * 60 * 60 * 1000; // 2 heures

    function docToData(documentSnapshot) {
      const data = documentSnapshot.data();
      const createdAt = data.createdAt && data.createdAt.toDate ? data.createdAt.toDate() : null;
      return {
        id: documentSnapshot.id,
        ...data,
        createdAtText: createdAt ? createdAt.toLocaleString("fr-FR") : (data.date || "")
      };
    }

    window.quizDB = {
      isReady: true,

      async createStudent(student) {
        const code = String(student.code || "").trim().toUpperCase();
        if (!code) throw new Error("Code etudiant obligatoire");
        await setDoc(doc(db, "etudiants_quiz", code), {
          ...student,
          code,
          createdAt: serverTimestamp()
        }, { merge: true });
        return true;
      },

      async getStudents() {
        const snapshot = await getDocs(collection(db, "etudiants_quiz"));
        return snapshot.docs.map(docToData);
      },

      async getStudentByCode(code) {
        const normalizedCode = String(code || "").trim().toUpperCase();
        if (!normalizedCode) return null;
        const snap = await getDoc(doc(db, "etudiants_quiz", normalizedCode));
        return snap.exists() ? docToData(snap) : null;
      },

      async clearAllData() {
        const collections = ["resultats_quiz", "connexions_quiz", "sessions_actives"];
        for (const collectionName of collections) {
          const snapshot = await getDocs(collection(db, collectionName));
          await Promise.all(snapshot.docs.map((documentSnapshot) => deleteDoc(doc(db, collectionName, documentSnapshot.id))));
        }
        return true;
      },

      async saveResult(result) {
        await addDoc(collection(db, "resultats_quiz"), {
          ...result,
          createdAt: serverTimestamp()
        });
        return true;
      },

      async getLeaderboard() {
        const q = query(collection(db, "resultats_quiz"), orderBy("score", "desc"), limit(20));
        const snapshot = await getDocs(q);
        return snapshot.docs.map(docToData);
      },

      async getStudentHistory(code) {
        const q = query(collection(db, "resultats_quiz"), where("code", "==", code), orderBy("createdAt", "desc"), limit(50));
        const snapshot = await getDocs(q);
        return snapshot.docs.map(docToData);
      },

      async getAllResults() {
        const q = query(collection(db, "resultats_quiz"), orderBy("createdAt", "desc"), limit(1000));
        const snapshot = await getDocs(q);
        return snapshot.docs.map(docToData);
      },

      async saveConnection(connection) {
        await addDoc(collection(db, "connexions_quiz"), {
          ...connection,
          createdAt: serverTimestamp()
        });
        return true;
      },

      async getConnections() {
        const q = query(collection(db, "connexions_quiz"), orderBy("createdAt", "desc"), limit(1000));
        const snapshot = await getDocs(q);
        return snapshot.docs.map(docToData);
      },

      async acquireSessionLock(code, sessionId, device) {
        const ref = doc(db, "sessions_actives", code);
        const now = Date.now();
        return await runTransaction(db, async (transaction) => {
          const snap = await transaction.get(ref);
          if (snap.exists()) {
            const active = snap.data();
            const lastSeen = Number(active.lastSeen || 0);
            const sameSession = active.sessionId === sessionId;
            const expired = now - lastSeen > SESSION_TIMEOUT_MS;
            if (!sameSession && !expired) {
              return { ok: false, active };
            }
          }

          transaction.set(ref, {
            code,
            sessionId,
            device,
            lastSeen: now,
            createdAt: serverTimestamp()
          });
          return { ok: true };
        });
      },

      async releaseSessionLock(code, sessionId) {
        const ref = doc(db, "sessions_actives", code);
        await runTransaction(db, async (transaction) => {
          const snap = await transaction.get(ref);
          if (snap.exists() && snap.data().sessionId === sessionId) {
            transaction.delete(ref);
          }
        });
        return true;
      }
    };

    console.log("Firebase connecte : les resultats, connexions et sessions seront sauvegardes en ligne.");
    window.dispatchEvent(new Event("quizFirebaseReady"));
  `;
  document.body.appendChild(script);
})();
// ===== FIN : assets/js/core/database.js =====
// ===== FIN DU MODULE 1 : services-quiz.js =====

;

