function getAllStudentSettings() {
  try {
    return JSON.parse(localStorage.getItem(STUDENT_SETTINGS_KEY) || "{}");
  } catch (error) {
    console.warn("Parametres etudiant invalides, reinitialisation.", error);
    return {};
  }
}

function normalizeStudentSettings(saved = {}) {
  const validQuestionLimits = ["all", "10", "20", "30", "50"];
  const validDisplayModes = ["", "all", "one"];
  const validFontSizes = ["small", "normal", "large", "xlarge"];
  const seconds = Number(saved.secondsPerQuestion);

  return {
    ...DEFAULT_STUDENT_SETTINGS,
    cameraEnabled: saved.cameraEnabled === true,
    autoSubmitOnExit: saved.autoSubmitOnExit !== false,
    defaultDisplayMode: validDisplayModes.includes(saved.defaultDisplayMode) ? saved.defaultDisplayMode : "",
    questionLimit: validQuestionLimits.includes(String(saved.questionLimit)) ? String(saved.questionLimit) : "all",
    shuffleQuestions: saved.shuffleQuestions !== false,
    shuffleOptions: saved.shuffleOptions === true,
    timerEnabled: saved.timerEnabled !== false,
    secondsPerQuestion: [15, 30, 45, 60].includes(seconds) ? seconds : 30,
    showExplanations: saved.showExplanations !== false,
    darkMode: saved.darkMode === true,
    fontSize: validFontSizes.includes(saved.fontSize) ? saved.fontSize : "normal",
  };
}

function getCurrentStudentSettings() {
  if (!currentUser) return { ...DEFAULT_STUDENT_SETTINGS };
  const allSettings = getAllStudentSettings();
  return normalizeStudentSettings(allSettings[currentUser] || {});
}

function saveCurrentStudentSettings(settings) {
  if (!currentUser) return;
  const allSettings = getAllStudentSettings();
  allSettings[currentUser] = normalizeStudentSettings({
    ...(allSettings[currentUser] || {}),
    ...settings,
  });
  localStorage.setItem(STUDENT_SETTINGS_KEY, JSON.stringify(allSettings));
}

