function applyStudentAppearance(settings = getCurrentStudentSettings()) {
  const body = document.body;
  if (!body) return;
  body.classList.toggle("dark-mode", settings.darkMode === true);
  ["font-small", "font-normal", "font-large", "font-xlarge"].forEach((className) => body.classList.remove(className));
  body.classList.add(`font-${settings.fontSize || "normal"}`);
}

