function updateCameraSettingUI() {
  const settings = getCurrentStudentSettings();
  if (cameraSettingToggle) cameraSettingToggle.checked = settings.cameraEnabled;
  if (autoSubmitExitToggle) autoSubmitExitToggle.checked = settings.autoSubmitOnExit;
  if (defaultDisplayModeSetting) defaultDisplayModeSetting.value = settings.defaultDisplayMode;
  if (questionLimitSetting) questionLimitSetting.value = settings.questionLimit;
  if (shuffleQuestionsToggle) shuffleQuestionsToggle.checked = settings.shuffleQuestions;
  if (shuffleOptionsToggle) shuffleOptionsToggle.checked = settings.shuffleOptions;
  if (timerSettingToggle) timerSettingToggle.checked = settings.timerEnabled;
  if (secondsPerQuestionSetting) {
    secondsPerQuestionSetting.value = String(settings.secondsPerQuestion);
    secondsPerQuestionSetting.disabled = !settings.timerEnabled;
  }
  if (showExplanationsToggle) showExplanationsToggle.checked = settings.showExplanations;
  if (darkModeToggle) darkModeToggle.checked = settings.darkMode;
  if (fontSizeSetting) fontSizeSetting.value = settings.fontSize;

  if (cameraSettingStatus) {
    cameraSettingStatus.textContent = settings.cameraEnabled
      ? "Caméra activée : une photo sera demandée avant chaque révision."
      : "Caméra désactivée : les révisions commenceront sans photo.";
    cameraSettingStatus.classList.toggle("enabled", settings.cameraEnabled);
  }
  applyStudentAppearance(settings);
}

