async function isAllowedMatricule(matricule) {
  return !!(await findStudentByAccessCode(matricule));
}

async function ensureAllowedUsers() {
  const users = getUsers();
  let hasChanges = false;
  const students = await getAllStudentsFromList();
  students.forEach((student) => {
    if (!users[student.code]) {
      users[student.code] = { history: [] };
      hasChanges = true;
    }
  });
  if (hasChanges) setUsers(users);
}


function normalizeForSearch(value) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]/g, "");
}

function normalizePhone(value) {
  return String(value || "").replace(/\D/g, "");
}

function phonesMatchForRecovery(searchedPhone, personPhone) {
  if (!searchedPhone || !personPhone) return false;
  if (searchedPhone === personPhone) return true;

  // Tolere les numeros ivoiriens saisis avec ou sans le 0 initial.
  if (searchedPhone.length >= 9 && personPhone.length >= 9) {
    return searchedPhone.slice(-9) === personPhone.slice(-9);
  }

  return false;
}

function getAccessRecoveryList() {
  if (Array.isArray(window.ACCESS_RECOVERY_LIST)) return window.ACCESS_RECOVERY_LIST;
  if (typeof ACCESS_RECOVERY_LIST !== "undefined" && Array.isArray(ACCESS_RECOVERY_LIST)) return ACCESS_RECOVERY_LIST;
  return [];
}

function findRecoveryPersonByCode(code) {
  const normalizedCode = normalizeStudentCode(code);
  return getAccessRecoveryList().find((person) => studentMatchesAccessCode(person, normalizedCode)) || null;
}

function getDisplayNameByAccessCode(code) {
  const normalizedCode = normalizeStudentCode(code);
  const created = getLocalCreatedStudents().map(normalizeStudentRecord).find((student) => studentMatchesAccessCode(student, normalizedCode));
  if (created) return created.nom;

  const person = findRecoveryPersonByCode(normalizedCode);
  if (person) return person.nomPrenoms || person.nom || normalizedCode;

  if (typeof ALLOWED_ACCESS_CODES !== "undefined" && ALLOWED_ACCESS_CODES[normalizedCode]) {
    return ALLOWED_ACCESS_CODES[normalizedCode];
  }

  return normalizedCode;
}

function setRecoverCodeMessage(message, isError = false) {
  if (!recoverCodeMessage) return;
  recoverCodeMessage.textContent = message;
  recoverCodeMessage.style.color = isError ? "#dc2626" : "#16a34a";
}

function openRecoverCodePage() {
  if (!recoverCodeCard) return;
  if (authCard) authCard.classList.add("hidden");
  recoverCodeCard.classList.add("hidden");
  if (recoverFullNameInput) recoverFullNameInput.value = "";
  if (recoverPhoneInput) recoverPhoneInput.value = "";
  setRecoverCodeMessage("");
  if (recoverLoginBtn) recoverLoginBtn.classList.add("hidden");
}

function closeRecoverCodePage() {
  if (recoverCodeCard) recoverCodeCard.classList.add("hidden");
  if (authCard) authCard.classList.add("hidden");
  setRecoverCodeMessage("");
  if (recoverLoginBtn) recoverLoginBtn.classList.add("hidden");
}

async function recoverAccessCode() {
  const searchedName = normalizeForSearch(recoverFullNameInput ? recoverFullNameInput.value : "");
  const searchedPhone = normalizePhone(recoverPhoneInput ? recoverPhoneInput.value : "");

  if (!searchedName && !searchedPhone) {
    setRecoverCodeMessage("Entre ton nom et prenoms ou ton numero de telephone.", true);
    return;
  }

  const list = await getAllStudentsFromList();

  const found = list.find((person) => {
    const personName = normalizeForSearch(person.nomPrenoms || person.nom);
    const personPhone = normalizePhone(person.telephone);
    const nameMatches = searchedName && personName && personName.includes(searchedName);
    const phoneMatches = phonesMatchForRecovery(searchedPhone, personPhone);
    return nameMatches || phoneMatches;
  });

  if (!found) {
    setRecoverCodeMessage("Aucun code trouve. Verifie le nom, les prenoms ou le numero.", true);
    return;
  }

  setRecoverCodeMessage(`Ton code d'acces est : ${found.code}`);
  if (loginNameInput) loginNameInput.value = found.code;
  if (recoverLoginBtn) recoverLoginBtn.classList.remove("hidden");
}

function loginWithRecoveredCode() {
  if (!loginNameInput || !loginNameInput.value.trim()) {
    setRecoverCodeMessage("Recupere d'abord ton code avant de te connecter.", true);
    return;
  }
  if (recoverCodeCard) recoverCodeCard.classList.add("hidden");
  if (authCard) authCard.classList.add("hidden");
  loginStudent();
}

async function loginStudent() {
  // La connexion étudiante se fait désormais exclusivement sur le portail.
  if (!loginNameInput) {
    location.replace("index.html");
    return;
  }
  const name = loginNameInput.value.trim().toUpperCase();

  if (!name) {
    setAuthMessage("Renseigne ton code d'acces.", true);
    return;
  }

  const student = await findStudentByAccessCode(name);
  if (!student) {
    setAuthMessage("Code d'acces non autorise. Demande a l'admin de creer ton espace.", true);
    return;
  }

  // Ouverture immediate de l'espace etudiant apres validation locale.
  // Firebase se synchronise ensuite via les fonctions de sauvegarde.
  const accessCode = student.code || normalizeStudentCode(name);
  setSession(accessCode);
  setAuthMessage("Connexion reussie.");
  showStudentArea(accessCode);
  currentUserName = student.nom || currentUserName;
  userNameDisplay.textContent = `👤 ${currentUserName}`;
  saveConnectionLog("connexion");
}

function logoutStudent() {
  stopQuizTimer();
  stopSingleQuestionTimer();
  saveConnectionLog("deconnexion");
  if (currentUser && currentSessionId && window.quizDB && window.quizDB.isReady) {
    window.quizDB.releaseSessionLock(currentUser, currentSessionId).catch((error) => console.error("Erreur liberation session", error));
  }
  clearSession();
  currentUser = "";
  currentUserName = "";
  currentSessionId = "";
  applyStudentAppearance({ ...DEFAULT_STUDENT_SETTINGS });
  resetCameraState();
  hideAllCards();
  location.replace("index.html");
}

async function restoreSession() {
  if (window.__quizSessionRestored && currentUser) return true;
  if (window.__quizSessionRestorePromise) return window.__quizSessionRestorePromise;

  window.__quizSessionRestorePromise = (async () => {
    const hubSession = window.RevisionHub && RevisionHub.getSession();
    if (!hubSession || !hubSession.code) return false;

    // La session a deja ete validee par le portail commun. La liste interne du
    // Quiz ne doit jamais annuler cette connexion si Firebase est lent ou si
    // ses donnees locales ne sont pas encore synchronisees.
    const student = getAllStudentsLocalOnly().find(student => studentMatchesAccessCode(student, hubSession.code)) || {
      code: normalizeStudentCode(hubSession.code),
      nom: hubSession.name || "Etudiant",
      telephone: hubSession.phone || ""
    };

    const accessCode = student.code || normalizeStudentCode(hubSession.code);
    setSession(accessCode, student);
    setAuthMessage("Connexion commune restaurée.");
    showStudentArea(accessCode);
    currentUserName = student.nom || hubSession.name || currentUserName;
    userNameDisplay.textContent = `👤 ${currentUserName}`;
    window.__quizSessionRestored = true;
    const loadingScreen = document.getElementById("quiz-loading-screen");
    if (loadingScreen) loadingScreen.remove();
    saveConnectionLog("connexion");
    return true;
  })();

  try {
    return await window.__quizSessionRestorePromise;
  } finally {
    window.__quizSessionRestorePromise = null;
  }
}


function getQuizData() {
  if (typeof QUIZ_QUESTIONS_BY_SUBJECT_AND_TOPIC !== "undefined" && QUIZ_QUESTIONS_BY_SUBJECT_AND_TOPIC) {
    return QUIZ_QUESTIONS_BY_SUBJECT_AND_TOPIC;
  }
  return {};
}

function getQuizSubjectsFromData() {
  const data = getQuizData();
  const dataSubjects = Object.keys(data).filter((subjectName) => {
    const topics = data[subjectName] || {};
    return Object.keys(topics).some((topicName) => Array.isArray(topics[topicName]) && topics[topicName].length > 0);
  });

  const config = typeof SUBJECTS_CONFIG !== "undefined" && Array.isArray(SUBJECTS_CONFIG) ? SUBJECTS_CONFIG : [];
  const ordered = [];
  config.forEach((subject) => {
    const name = subject.subjectName || subject;
    if (dataSubjects.includes(name) && !ordered.includes(name)) ordered.push(name);
  });
  dataSubjects.forEach((name) => {
    if (!ordered.includes(name)) ordered.push(name);
  });
  return ordered.map((subjectName) => ({ subjectName, displayName: subjectName }));
}

function getTopicsForSubjectFromData(subjectName) {
  const data = getQuizData();
  return Object.keys(data[subjectName] || {}).filter((topicName) => {
    return Array.isArray(data[subjectName][topicName]) && data[subjectName][topicName].length > 0;
  });
}

const DE_BLANC_2026_DOCUMENTS = {"D.E. BLANC 2026 — Chirurgie — Agboville — IDE": {"subject": "Chirurgie", "url": "de-blanc-2026-agboville-ide.pdf#page=1"}, "D.E. BLANC 2026 — Chirurgie — Daloa — IDE": {"subject": "Chirurgie", "url": "de-blanc-2026-daloa-ide.pdf#page=1"}, "D.E. BLANC 2026 — Chirurgie — Korhogo — IDE": {"subject": "Chirurgie", "url": "de-blanc-2026-korhogo-ide.pdf#page=1"}, "D.E. BLANC 2026 — Médecine — Agboville — IDE": {"subject": "Médecine", "url": "de-blanc-2026-agboville-ide.pdf#page=4"}, "D.E. BLANC 2026 — Médecine — Daloa — IDE": {"subject": "Médecine", "url": "de-blanc-2026-daloa-ide.pdf#page=11"}, "D.E. BLANC 2026 — Médecine — Korhogo — IDE": {"subject": "Médecine", "url": "de-blanc-2026-korhogo-ide.pdf#page=11"}, "D.E. BLANC 2026 — Pédiatrie — Agboville — IDE": {"subject": "Pédiatrie", "url": "de-blanc-2026-agboville-ide.pdf#page=9"}, "D.E. BLANC 2026 — Pédiatrie — Agboville — SFM": {"subject": "Pédiatrie", "url": "de-blanc-2026-agboville-sfm.pdf#page=5"}, "D.E. BLANC 2026 — Pédiatrie — Daloa — IDE": {"subject": "Pédiatrie", "url": "de-blanc-2026-daloa-ide.pdf#page=17"}, "D.E. BLANC 2026 — Pédiatrie — Daloa — SFM": {"subject": "Pédiatrie", "url": "de-blanc-2026-daloa-sfm.pdf#page=1"}, "D.E. BLANC 2026 — Pédiatrie — Korhogo — IDE": {"subject": "Pédiatrie", "url": "de-blanc-2026-korhogo-ide.pdf#page=17"}, "D.E. BLANC 2026 — Pédiatrie — Korhogo — SFM": {"subject": "Pédiatrie", "url": "de-blanc-2026-korhogo-sfm.pdf#page=10"}, "D.E. BLANC 2026 — Santé Publique — Agboville — IDE": {"subject": "Santé Publique", "url": "de-blanc-2026-agboville-ide.pdf#page=13"}, "D.E. BLANC 2026 — Santé Publique — Agboville — SFM": {"subject": "Santé Publique", "url": "de-blanc-2026-agboville-sfm.pdf#page=12"}, "D.E. BLANC 2026 — Santé Publique — Daloa — IDE": {"subject": "Santé Publique", "url": "de-blanc-2026-daloa-ide.pdf#page=21"}, "D.E. BLANC 2026 — Santé Publique — Daloa — SFM": {"subject": "Santé Publique", "url": "de-blanc-2026-daloa-sfm.pdf#page=5"}, "D.E. BLANC 2026 — Santé Publique — Korhogo — IDE": {"subject": "Santé Publique", "url": "de-blanc-2026-korhogo-ide.pdf#page=23"}, "D.E. BLANC 2026 — Santé Publique — Korhogo — SFM": {"subject": "Santé Publique", "url": "de-blanc-2026-korhogo-sfm.pdf#page=16"}, "D.E. BLANC 2026 — Gynécologie — Agboville — SFM": {"subject": "Gynécologie", "url": "de-blanc-2026-agboville-sfm.pdf#page=1"}, "D.E. BLANC 2026 — Gynécologie — Korhogo — SFM": {"subject": "Gynécologie", "url": "de-blanc-2026-korhogo-sfm.pdf#page=1"}, "D.E. BLANC 2026 — Planification Familiale / SR — Agboville — SFM": {"subject": "Planification Familiale / SR", "url": "de-blanc-2026-agboville-sfm.pdf#page=9"}, "D.E. BLANC 2026 — Planification Familiale / SR — Korhogo — SFM": {"subject": "Planification Familiale / SR", "url": "de-blanc-2026-korhogo-sfm.pdf#page=23"}};
function formatSubjectTitle(title) {
  const raw = String(title || '').trim();
  if (!raw) return raw;
  const subjects = {
    'CHIRURGIE': 'Chirurgie', 'MÉDECINE': 'Médecine', 'PÉDIATRIE': 'Pédiatrie',
    'SANTÉ PUBLIQUE': 'Santé publique', 'GYNÉCOLOGIE': 'Gynécologie-obstétrique',
    'GYNÉCOLOGIE-OBSTÉTRIQUE': 'Gynécologie-obstétrique',
    'SSR/PF': 'SSR / Planification familiale',
    'PLANIFICATION FAMILIALE / SR': 'SSR / Planification familiale'
  };
  const subjectLabel = name => subjects[name.trim().toUpperCase()] || name.trim();
  const pdf = raw.match(/^D\.E\. BLANC (\d{4}) — (.+?) — (.+?) — (IDE|SFM)$/i);
  if (pdf) return `D.E. BLANC ${pdf[1]} — ${subjectLabel(pdf[2])} — Antenne ${pdf[3]} — ${pdf[4]}`;
  const deb = raw.match(/^DEB (.+?) (\d{4}) antenne (.+)$/i);
  if (deb) {
    let city = deb[3].replace(/\s+N°\s*(\d+)$/i, ' — Sujet $1').replace(/\s+Groupe\s+(\d+)$/i, ' — Groupe $1');
    return `D.E. BLANC ${deb[2]} — ${subjectLabel(deb[1])} — Antenne ${city}`;
  }
  const prep = raw.match(/^PREPA D\.E\.? NATIONALE (\d{4}) (.+?) (IDE(?:[\/-]SFM)?|SFM) SUJET\s*(\d+)$/i);
  if (prep) return `PRÉPA D.E. NATIONALE ${prep[1]} — ${subjectLabel(prep[2])} — ${prep[3].replace('IDE-SFM', 'IDE/SFM')} — Sujet ${prep[4]}`;
  return raw;
}

function getPreparationSubjectsWithQuestions() {
  const prepConfig = typeof PREPARATION_DE_CONFIG !== "undefined" && Array.isArray(PREPARATION_DE_CONFIG) ? PREPARATION_DE_CONFIG : [];
  const prepLabels = typeof PREPARATION_DE_SUBJECTS !== "undefined" && Array.isArray(PREPARATION_DE_SUBJECTS) ? PREPARATION_DE_SUBJECTS : [];
  const labelBySubject = new Map(prepLabels.map((item) => [item.subjectName, item.label || item.subjectName]));

  const available = prepConfig
    .filter((subject) => {
      const topics = Array.isArray(subject.topics) ? subject.topics : [];
      return topics.some((topicName) => isTopicForActivePortal(topicName) && (getQuizData()[subject.subjectName]?.[topicName] || []).length > 0);
    })
    .map((subject) => ({ ...subject, displayName: labelBySubject.get(subject.subjectName) || subject.subjectName }));
  if (PORTAL_VARIANT === "de-blanc") {
    for (const doc of Object.values(DE_BLANC_2026_DOCUMENTS)) {
      if (!available.some(item => item.subjectName === doc.subject)) available.push({ subjectName: doc.subject, displayName: doc.subject, topics: [] });
    }
  }
  return available;
}

function isTopicForActivePortal(topicName) {
  const normalizedTopic = normalizeForSearch(topicName);
  const isPrepaNational2026 = normalizedTopic.includes("prepadenationale2026");
  return PORTAL_VARIANT === "prepa-national" ? isPrepaNational2026 : !isPrepaNational2026;
}

function findQuestionsForSelection(subjectName, topicName) {
  const data = getQuizData();
  if (data[subjectName] && Array.isArray(data[subjectName][topicName])) {
    return data[subjectName][topicName];
  }

  const normalizedSubject = normalizeForSearch(subjectName);
  const realSubject = Object.keys(data).find((key) => normalizeForSearch(key) === normalizedSubject);
  if (!realSubject) return [];

  const normalizedTopic = normalizeForSearch(topicName);
  const realTopic = Object.keys(data[realSubject] || {}).find((key) => normalizeForSearch(key) === normalizedTopic);
  return realTopic && Array.isArray(data[realSubject][realTopic]) ? data[realSubject][realTopic] : [];
}

function cloneQuestionForRevision(question, shouldShuffleOptions = false) {
  const cloned = {
    ...question,
    options: Array.isArray(question.options) ? [...question.options] : [],
    answer: Array.isArray(question.answer) ? [...question.answer] : question.answer,
  };

  if (!shouldShuffleOptions || cloned.options.length < 2) return cloned;

  const indexedOptions = cloned.options.map((text, oldIndex) => ({ text, oldIndex }));
  const shuffledOptions = shuffleArray(indexedOptions);
  const newIndexByOldIndex = new Map(
    shuffledOptions.map((item, newIndex) => [item.oldIndex, newIndex])
  );

  cloned.options = shuffledOptions.map((item) => item.text);
  const remapAnswer = (answerIndex) => {
    const numericIndex = Number(answerIndex);
    return newIndexByOldIndex.has(numericIndex)
      ? newIndexByOldIndex.get(numericIndex)
      : answerIndex;
  };
  cloned.answer = Array.isArray(cloned.answer)
    ? cloned.answer.map(remapAnswer)
    : remapAnswer(cloned.answer);

  return cloned;
}

function prepareQuestionsForQuiz(sourceQuestions) {
  const settings = getCurrentStudentSettings();
  let prepared = Array.isArray(sourceQuestions) ? [...sourceQuestions] : [];

  if (settings.shuffleQuestions) prepared = shuffleArray(prepared);

  if (settings.questionLimit !== "all") {
    const limit = Number(settings.questionLimit);
    if (Number.isFinite(limit) && limit > 0) prepared = prepared.slice(0, limit);
  }

  return prepared.map((question) => cloneQuestionForRevision(question, settings.shuffleOptions));
}

function getEffectiveQuestionCount(total) {
  const limitSetting = getCurrentStudentSettings().questionLimit;
  if (limitSetting === "all") return total;
  const limit = Number(limitSetting);
  return Number.isFinite(limit) && limit > 0 ? Math.min(total, limit) : total;
}

function getActiveSubjectsConfig() {
  if (selectedMode === "preparation" && typeof PREPARATION_DE_CONFIG !== "undefined") {
    return PREPARATION_DE_CONFIG;
  }
  return SUBJECTS_CONFIG;
}

function renderTopicsForSelectedSubject(subjectName) {
  topicChoiceSelect.innerHTML = "";
  topicChoiceSelect.disabled = !subjectName;

  const placeholderOption = createPlaceholderOption(
    subjectName ? "Choisis un sujet" : "Choisis une matière d'abord"
  );
  topicChoiceSelect.appendChild(placeholderOption);

  if (subjectName) {
    let topics = [];
    if (selectedMode === "preparation") {
      const prepConfig = typeof PREPARATION_DE_CONFIG !== "undefined" && Array.isArray(PREPARATION_DE_CONFIG) ? PREPARATION_DE_CONFIG : [];
      const subjectConfig = prepConfig.find((item) => item.subjectName === subjectName);
      topics = (subjectConfig?.topics || []).filter((topicName) => isTopicForActivePortal(topicName) && findQuestionsForSelection(subjectName, topicName).length > 0);
    } else {
      topics = getTopicsForSubjectFromData(subjectName);
    }

    if (!topics.length) {
      const subjectsConfig = getActiveSubjectsConfig();
      const subjectConfig = subjectsConfig.find((item) => item.subjectName === subjectName);
      topics = subjectConfig?.topics || [];
    }

    if (PORTAL_VARIANT === "de-blanc" && selectedMode === "preparation") {
      topics = topics.sort((a, b) => Number(b.includes("BLANC 2026")) - Number(a.includes("BLANC 2026")));
    }
    topics.forEach((topic) => {
      const option = document.createElement("option");
      option.value = topic;
      option.textContent = formatSubjectTitle(topic);
      topicChoiceSelect.appendChild(option);
    });
  }

  selectedTopicName = "";
  updateBeginQuizButtonState();
  updateSelectedQuestionCount();
}

function updateQuizButtonLabel() {
  generalQuizBtn.textContent = "QUIZ";
}

function updateSelectedQuestionCount() {
  if (!selectedSubjectName || !selectedTopicName || !QUIZ_QUESTIONS_BY_SUBJECT_AND_TOPIC) {
    selectedQuestionCount.textContent = "";
    return;
  }

  const count = findQuestionsForSelection(selectedSubjectName, selectedTopicName).length || 0;
  const effectiveCount = getEffectiveQuestionCount(count);
  selectedQuestionCount.textContent = count
    ? effectiveCount === count
      ? `Nombre de questions pour ce sujet : ${count}`
      : `Ce sujet contient ${count} questions. Cette révision utilisera ${effectiveCount} questions selon tes paramètres.`
    : "Aucune question disponible pour ce sujet.";
}

function applyPreparationDEFilter() {
  const subjects = getPreparationSubjectsWithQuestions();
  populateSubjectSelect(subjects, "Choisis une matière", "preparation");
  if (!subjects.length) {
    setSubjectMessage(`Aucun sujet disponible dans ${PORTAL_TITLE}.`, true);
  }
  updateBeginQuizButtonState();
}

function handleGeneralQuizButton() {
  const subjects = getQuizSubjectsFromData();
  populateSubjectSelect(subjects, "Choisis une matière", "quiz");
  if (!subjects.length) {
    setSubjectMessage("Aucune matière disponible. Vérifie le fichier quiz-data.js.", true);
  }
  updateBeginQuizButtonState();
}

function handlePreparationDeButton() {
  applyPreparationDEFilter();
}

function initSubjectSelection() {
  applyPreparationDEFilter();
  if (displayModeChoiceSelect) {
    displayModeChoiceSelect.value = "";
    applyPreferredDisplayMode();
  }
  unlockChoiceMenus();
}

function startQuiz() {
  if (!currentUser) {
    location.replace("index.html");
    return;
  }

  if (!selectedSubjectName) {
    setSubjectMessage("Selectionne une matiere.", true);
    return;
  }

  if (!selectedTopicName) {
    setSubjectMessage("Selectionne un sujet.", true);
    return;
  }

  const cameraRequired = isCameraEnabledForCurrentUser();
  if (cameraRequired && !hasCapturedPhoto) {
    subjectsCard.classList.add("hidden");
    quizCard.classList.add("hidden");
    resultCard.classList.add("hidden");
    startCard.classList.remove("hidden");
    resetCameraState();
    setCameraMessage("Tu as activé la caméra dans Paramètres. Active-la puis prends une photo pour commencer.");
    return;
  }

  currentQuestions = prepareQuestionsForQuiz(findQuestionsForSelection(selectedSubjectName, selectedTopicName));
  if (currentQuestions.length === 0) {
    setSubjectMessage("Aucune question disponible pour ce sujet.", true);
    return;
  }

  score = 0;
  quizSubmitted = false;
  autoSubmitLocked = false;
  lastAutoSubmitReason = "";
  userAnswers = Array(currentQuestions.length).fill(null);
  currentQuestionIndex = 0;
  selectedDisplayMode = displayModeChoiceSelect ? displayModeChoiceSelect.value : "all";
  answersReview.length = 0;

  startCard.classList.add("hidden");
  subjectsCard.classList.add("hidden");
  resultCard.classList.add("hidden");
  quizCard.classList.remove("hidden");
  quizUserName.textContent = `👤 ${currentUserName}`;

  if (selectedDisplayMode === "one") {
    renderSingleQuestion();
  } else {
    renderAllQuestions();
    startQuizTimer();
  }
}

function saveAnswerForQuestion(questionIndex, optionIndex, isMultipleAnswer) {
  if (isMultipleAnswer) {
    const selected = Array.from(
      document.querySelectorAll(`input[name="question-${questionIndex}"]:checked`)
    ).map((item) => Number(item.value));
    userAnswers[questionIndex] = selected.length ? selected : null;
  } else {
    userAnswers[questionIndex] = optionIndex;
  }
}

function buildQuestionElement(q, questionIndex) {
  const wrapper = document.createElement("div");
  wrapper.className = "review-item question-block";
  const title = document.createElement("strong");
  title.textContent = `${questionIndex + 1}. ${cleanQuestionText(q.question)}`;
  title.style.whiteSpace = "pre-wrap";
  wrapper.appendChild(title);
  if (q.correctionAuthor) {
    const hint = document.createElement("p");
    hint.textContent = q.neutralized ? "Question non notée — explication après validation." : q.multiple ? "Plusieurs réponses possibles : sélectionner toutes les réponses pertinentes." : "Une réponse à sélectionner.";
    wrapper.appendChild(hint);
  }

  const expectedAnswers = Array.isArray(q.answer) ? q.answer : [q.answer];
  const isMultipleAnswer = q.ungraded ? Boolean(q.multiple) : expectedAnswers.length > 1;
  const savedAnswer = userAnswers[questionIndex];
  const savedAnswers = Array.isArray(savedAnswer)
    ? savedAnswer
    : savedAnswer === null
    ? []
    : [savedAnswer];

  const options = Array.isArray(q.options) ? q.options : [];
  options.forEach((optionText, optionIndex) => {
    const label = document.createElement("label");
    label.className = "answer-choice";

    const input = document.createElement("input");
    input.type = isMultipleAnswer ? "checkbox" : "radio";
    input.name = `question-${questionIndex}`;
    input.value = String(optionIndex);
    input.checked = savedAnswers.includes(optionIndex);
    input.style.width = "auto";
    input.style.marginRight = "8px";
    input.addEventListener("change", () => {
      saveAnswerForQuestion(questionIndex, optionIndex, isMultipleAnswer);
    });

    label.appendChild(input);
    label.append(optionText);
    wrapper.appendChild(label);
  });

  return wrapper;
}

function renderAllQuestions() {
  selectedDisplayMode = "all";
  questionCount.textContent = `Questions: ${currentQuestions.length}`;
  scoreLive.textContent = "Score: -";
  updateTimerDisplay();
  questionText.textContent = "Toutes les questions";
  answersContainer.innerHTML = "";
  if (singleQuestionNav) singleQuestionNav.classList.add("hidden");
  submitAnswersBtn.classList.remove("hidden");
  submitAnswersBtn.textContent = "Valider mes reponses";

  currentQuestions.forEach((q, questionIndex) => {
    answersContainer.appendChild(buildQuestionElement(q, questionIndex));
  });
}

function renderSingleQuestion() {
  selectedDisplayMode = "one";
  const total = currentQuestions.length;
  const q = currentQuestions[currentQuestionIndex];
  if (!q) {
    answersContainer.innerHTML = "";
    questionText.textContent = "Aucune question disponible";
    return;
  }
  questionCount.textContent = `Question ${currentQuestionIndex + 1}/${total}`;
  scoreLive.textContent = "Score: -";
  updateTimerDisplay();
  questionText.textContent = "Question par question";
  answersContainer.innerHTML = "";
  answersContainer.appendChild(buildQuestionElement(q, currentQuestionIndex));
  startSingleQuestionTimer();

  if (singleQuestionNav) singleQuestionNav.classList.remove("hidden");
  if (prevQuestionBtn) prevQuestionBtn.disabled = currentQuestionIndex === 0;
  if (nextQuestionBtn) {
    nextQuestionBtn.textContent = currentQuestionIndex === total - 1 ? "Dernière question" : "Suivant →";
    nextQuestionBtn.disabled = currentQuestionIndex === total - 1;
  }
  submitAnswersBtn.classList.remove("hidden");
  submitAnswersBtn.textContent = currentQuestionIndex === total - 1
    ? "Valider mes reponses"
    : "Valider maintenant";
}

function goToPreviousQuestion() {
  if (selectedDisplayMode !== "one" || currentQuestionIndex <= 0) return;
  currentQuestionIndex -= 1;
  renderSingleQuestion();
}

function goToNextQuestion() {
  if (selectedDisplayMode !== "one" || currentQuestionIndex >= currentQuestions.length - 1) return;
  currentQuestionIndex += 1;
  renderSingleQuestion();
}

function submitAllAnswers() {
  finalizeQuizSubmission({ allowIncomplete: true, reason: "" });
}

function finalizeQuizSubmission({ allowIncomplete = false, reason = "" } = {}) {
  if (quizSubmitted || currentQuestions.length === 0) return;

  if (!allowIncomplete && userAnswers.some((answer) => answer === null)) {
    questionText.textContent = "Reponds aux questions avant de valider.";
    return;
  }

  quizSubmitted = true;
  stopQuizTimer();
  stopSingleQuestionTimer();
  lastAutoSubmitReason = reason;
  let goodAnswers = 0;
  let badAnswers = 0;
  let unanswered = 0;
  answersReview.length = 0;

  let gradedTotal = 0;
  let rawPoints = 0;
  currentQuestions.forEach((q, questionIndex) => {
    const chosenAnswer = userAnswers[questionIndex];
    const expectedAnswers = q.answer == null ? [] : Array.isArray(q.answer) ? [...q.answer].sort((a, b) => a - b) : [q.answer];
    const chosenAnswers = Array.isArray(chosenAnswer)
      ? [...chosenAnswer].sort((a, b) => a - b)
      : chosenAnswer == null ? [] : [chosenAnswer];
    const neutralized = Boolean(q.ungraded || q.neutralized || expectedAnswers.length === 0);
    const isCorrect = !neutralized && chosenAnswers.length === expectedAnswers.length &&
      chosenAnswers.every((answer, index) => answer === expectedAnswers[index]);
    const isQCD = q.type === "QCD" || (!q.type && q.options.length === 2 &&
      q.options.every(option => /^(?:[AB]\.\s*)?(vrai|faux)$/i.test(option.trim())));
    if (!neutralized) {
      gradedTotal += 1;
      if (isCorrect) { goodAnswers += 1; rawPoints += 1; }
      else if (chosenAnswers.length === 0) unanswered += 1;
      else { badAnswers += 1; if (isQCD) rawPoints -= 1; }
    }
    answersReview.push({
      question: cleanQuestionText(q.question), isCorrect, neutralized,
      explanation: q.explanation, source: q.correctionSource || q.source || "",
      references: q.references || [], questionSource: q.questionSource || "",
      correctionAuthor: q.correctionAuthor || "", revisionNotes: q.revisionNotes || [],
      originalQuestion: q.originalQuestion || "", originalOptions: q.originalOptions || [],
      goodAnswer: neutralized ? "Question exclue de la note" : expectedAnswers.map(i => q.options[i]).join(" / "),
      userAnswer: chosenAnswers.length ? chosenAnswers.map(i => q.options[i]).join(" / ") : "Non répondu"
    });
  });
  // Each valid question is worth one point. Only a wrong QCD loses one point.
  // Neutralized questions never enter the denominator or the penalty.
  score = gradedTotal ? Math.max(0, Math.round(rawPoints * 20 / gradedTotal * 100) / 100) : null;
  showResults(reason, goodAnswers, badAnswers, unanswered, gradedTotal);
}

function autoSubmitQuiz(reason) {
  const quizIsOpen =
    currentUser &&
    currentQuestions.length > 0 &&
    !quizSubmitted &&
    !quizCard.classList.contains("hidden");

  if (!quizIsOpen || autoSubmitLocked) return;

  autoSubmitLocked = true;
  finalizeQuizSubmission({ allowIncomplete: true, reason });
}

function showResults(reason = "", goodAnswers = 0, badAnswers = 0, unanswered = 0, total = 0) {
  quizCard.classList.add("hidden");
  resultCard.classList.remove("hidden");
  const excluded = answersReview.filter(item => item.neutralized).length;
  const authored = currentQuestions.some(q => q.correctionAuthor);
  finalMessage.innerHTML = "";
  const status = document.createElement("p");
  status.textContent = reason ? `Quiz envoyé automatiquement (${reason}).` : "Quiz terminé.";
  finalMessage.appendChild(status);
  const details = document.createElement("div");
  details.style.cssText = "background:#f0f9ff;padding:15px;border-radius:8px;margin-bottom:20px";
  const lines = [total ? `Note : ${score}/20` : "Note non calculée : aucune question notée.",
    `Bonnes réponses : ${goodAnswers}/${total} ; mauvaises : ${badAnswers}/${total} ; non répondues : ${unanswered}/${total}.`,
    "Barème par question : réponse exacte +1 ; QCM faux ou incomplet 0 ; QCD faux −1 ; sans réponse 0. Note ramenée sur 20, minimum 0."];
  if (excluded) lines.push(`${excluded} question(s) exclue(s) de la note : voir les explications ci-dessous.`);
  if (authored) lines.push("Corrigé pédagogique rédigé par ChatGPT, non officiel. Les énoncés rectifiés et les références sont indiqués dans la correction.");
  lines.forEach(text => { const p = document.createElement("p"); p.textContent = text; details.appendChild(p); });
  finalMessage.appendChild(details);
  reviewList.innerHTML = "";
  const showExplanations = getCurrentStudentSettings().showExplanations;
  answersReview.forEach(item => {
    const div = document.createElement("div");
    div.className = `review-item ${item.neutralized ? "neutralized" : item.isCorrect ? "good" : "bad"}`;
    const heading = document.createElement("strong"); heading.textContent = item.question; heading.style.whiteSpace = "pre-wrap"; div.appendChild(heading);
    const line = text => { const p = document.createElement("p"); p.textContent = text; div.appendChild(p); };
    line(`Ta réponse : ${item.userAnswer}`);
    line(`${item.neutralized ? "Statut" : "Bonne réponse"} : ${item.goodAnswer}`);
    if ((showExplanations || item.correctionAuthor || item.neutralized) && item.explanation) line(item.explanation);
    if (item.source) line(`Fondement du corrigé : ${item.source}`);
    if (item.questionSource) line(`Sujet d’origine : ${item.questionSource}`);
    item.references.forEach(ref => {
      if (!/^https:\/\//.test(ref.url)) return;
      const p = document.createElement("p"), a = document.createElement("a");
      a.href = ref.url; a.textContent = ref.title; a.target = "_blank"; a.rel = "noopener noreferrer"; p.appendChild(a); div.appendChild(p);
    });
    if (item.revisionNotes.length) {
      line(item.revisionNotes.join(" "));
      const disclosure = document.createElement("details"), summary = document.createElement("summary");
      summary.textContent = "Voir l’énoncé et les choix avant rectification"; disclosure.appendChild(summary);
      const original = document.createElement("p"); original.textContent = item.originalQuestion; original.style.whiteSpace = "pre-wrap"; disclosure.appendChild(original);
      item.originalOptions.forEach((text, i) => { const p = document.createElement("p"); p.textContent = `${String.fromCharCode(65+i)}. ${text}`; disclosure.appendChild(p); });
      div.appendChild(disclosure);
    }
    reviewList.appendChild(div);
  });
  if (total) { saveScore(currentUser, score); renderLeaderboard(); }
}


function addPendingItem(key, item) {
  const list = JSON.parse(localStorage.getItem(key) || "[]");
  const itemWithId = { ...item, localId: item.localId || `${Date.now()}-${Math.random().toString(36).slice(2)}` };
  list.unshift(itemWithId);
  localStorage.setItem(key, JSON.stringify(list.slice(0, 1000)));
  return itemWithId;
}

function removePendingItem(key, localId) {
  if (!localId) return;
  const list = JSON.parse(localStorage.getItem(key) || "[]");
  localStorage.setItem(key, JSON.stringify(list.filter((item) => item.localId !== localId)));
}

async function syncPendingFirebaseData() {
  await waitForFirebaseReady(5000);
  if (!window.quizDB || !window.quizDB.isReady) return false;

  const pendingResults = JSON.parse(localStorage.getItem(PENDING_RESULTS_KEY) || "[]");
  for (const item of [...pendingResults].reverse()) {
    try {
      const { localId, ...result } = item;
      await window.quizDB.saveResult(result);
      removePendingItem(PENDING_RESULTS_KEY, localId);
    } catch (error) {
      console.error("Erreur synchronisation resultat Firebase", error);
      break;
    }
  }

  const pendingConnections = JSON.parse(localStorage.getItem(PENDING_CONNECTIONS_KEY) || "[]");
  for (const item of [...pendingConnections].reverse()) {
    try {
      const { localId, ...connection } = item;
      await window.quizDB.saveConnection(connection);
      removePendingItem(PENDING_CONNECTIONS_KEY, localId);
    } catch (error) {
      console.error("Erreur synchronisation connexion Firebase", error);
      break;
    }
  }
  return true;
}

function schedulePendingSync() {
  syncPendingFirebaseData().catch((error) => console.error("Erreur synchronisation Firebase", error));
}

function saveScore(name, score) {
  const code = normalizeStudentCode(name || currentUser);
  const nowText = new Date().toLocaleString("fr-FR");
  const result = {
    code,
    name: code,
    nom: currentUserName || getDisplayNameByAccessCode(code),
    score,
    date: nowText,
    createdAtText: nowText,
    mode: lastAutoSubmitReason ? "automatique" : "manuel",
    reason: lastAutoSubmitReason || "",
    matiere: selectedSubjectName || "",
    sujet: formatSubjectTitle(selectedTopicName),
    type: selectedMode || "",
    displayMode: selectedDisplayMode || "",
    device: getDeviceLabel()
  };

  // Sauvegarde locale : fonctionne meme sans internet.
  const oldData = JSON.parse(localStorage.getItem(LEADERBOARD_KEY) || "[]");
  oldData.push({ name: code, code, nom: result.nom, score, date: result.date, createdAtText: result.createdAtText, matiere: result.matiere, sujet: result.sujet, mode: result.mode });
  oldData.sort((a, b) => Number(b.score || 0) - Number(a.score || 0));
  localStorage.setItem(LEADERBOARD_KEY, JSON.stringify(oldData.slice(0, 100)));

  // Sauvegarde dans l'espace etudiant. On cree l'entree si elle n'existe pas encore.
  const users = getUsers();
  if (!users[code]) users[code] = { history: [] };
  if (!Array.isArray(users[code].history)) users[code].history = [];
  users[code].history.unshift(result);
  users[code].history = users[code].history.slice(0, 200);
  setUsers(users);

  // Sauvegarde historique admin local.
  try {
    saveQuizHistory(result);
  } catch (error) {
    console.error("Erreur sauvegarde historique admin", error);
  }

  // Sauvegarde en ligne : mise en attente puis synchronisation Firebase.
  // Cela evite de perdre les notes quand Firebase charge lentement sur le telephone.
  addPendingItem(PENDING_RESULTS_KEY, result);
  schedulePendingSync();
}

async function renderLeaderboard() {
  leaderboardList.innerHTML = "";
  let data = [];

  await waitForFirebaseReady();

  if (window.quizDB && window.quizDB.isReady) {
    try {
      data = await window.quizDB.getLeaderboard();
    } catch (error) {
      console.error("Erreur lecture classement Firebase", error);
    }
  }

  if (!data.length) {
    data = JSON.parse(localStorage.getItem(LEADERBOARD_KEY) || "[]");
  }

  if (data.length === 0) {
    const li = document.createElement("li");
    li.textContent = "Aucun score pour le moment.";
    leaderboardList.appendChild(li);
    return;
  }

  data.forEach((row) => {
    const li = document.createElement("li");
    li.textContent = `${row.nom || row.name || row.code} - ${row.score}/20 (${row.date || "date non disponible"})`;
    leaderboardList.appendChild(li);
  });
}

async function renderStudentHistory() {
  if (studentHistoryList) studentHistoryList.innerHTML = "";
  if (studentSummary) studentSummary.innerHTML = "";

  const code = normalizeStudentCode(currentUser);
  let history = [];
  const addRows = (rows) => {
    (rows || []).forEach((row) => {
      const rowCode = normalizeStudentCode(row.code || row.name || row.matricule || row.studentCode);
      if (rowCode === code) history.push(normalizeResultRecord({ ...row, code: rowCode }));
    });
  };

  await waitForFirebaseReady(2500);

  if (window.quizDB && window.quizDB.isReady) {
    try {
      addRows(await window.quizDB.getStudentHistory(code));
    } catch (error) {
      console.error("Erreur historique Firebase", error);
    }
  }

  const users = getUsers();
  addRows(users[code]?.history || []);
  addRows(JSON.parse(localStorage.getItem("quiz_history") || "[]"));
  addRows(JSON.parse(localStorage.getItem(PENDING_RESULTS_KEY) || "[]"));
  addRows(JSON.parse(localStorage.getItem(LEADERBOARD_KEY) || "[]"));

  const seen = new Set();
  history = history
    .filter((row) => row.code === code && row.score !== null && row.score !== undefined && row.score !== "")
    .filter((row) => {
      const signature = [row.code, row.createdAtText || row.date, row.matiere || "", row.sujet || "", row.score ?? "", row.mode || ""].join("|");
      if (seen.has(signature)) return false;
      seen.add(signature);
      return true;
    })
    .sort((a, b) => parseHistoryDate(b.createdAtText || b.date) - parseHistoryDate(a.createdAtText || a.date));

  if (history.length === 0) {
    const li = document.createElement("li");
    li.textContent = "Aucun resultat pour le moment.";
    studentHistoryList.appendChild(li);
    return;
  }

  const scores = history.map((row) => Number(row.score)).filter((n) => Number.isFinite(n));
  const avg = scores.length ? (scores.reduce((a, b) => a + b, 0) / scores.length).toFixed(2) : "0";
  const best = scores.length ? Math.max(...scores) : 0;
  if (studentSummary) {
    studentSummary.innerHTML = `
      <div class="stat-card"><strong>${history.length}</strong><span>Notes</span></div>
      <div class="stat-card"><strong>${avg}/20</strong><span>Moyenne</span></div>
      <div class="stat-card"><strong>${best}/20</strong><span>Meilleure note</span></div>
    `;
  }

  history.forEach((row) => {
    const li = document.createElement("li");
    const date = row.createdAtText || row.date || "date non disponible";
    li.innerHTML = `<strong>${escapeHtml(row.score)}/20</strong> - ${escapeHtml(row.matiere || "Matiere")}${row.sujet ? " / " + escapeHtml(row.sujet) : ""}<br><span class="muted">${escapeHtml(date)}${row.mode === "automatique" ? " - envoi automatique" : ""}</span>`;
    studentHistoryList.appendChild(li);
  });
}

function saveConnectionLog(action) {
  if (!currentUser) return;
  const nowText = new Date().toLocaleString("fr-FR");
  const connection = {
    code: currentUser,
    nom: currentUserName || getDisplayNameByAccessCode(currentUser),
    action,
    device: getDeviceLabel(),
    date: nowText,
    createdAtText: nowText
  };

  const local = JSON.parse(localStorage.getItem("quizPromoConnections") || "[]");
  local.unshift(connection);
  localStorage.setItem("quizPromoConnections", JSON.stringify(local.slice(0, 200)));

  addPendingItem(PENDING_CONNECTIONS_KEY, connection);
  schedulePendingSync();
}

function setCreateStudentMessage(message, isError = false) {
  if (!createStudentMessage) return;
  createStudentMessage.textContent = message;
  createStudentMessage.style.color = isError ? "#dc2626" : "#16a34a";
}

function updateGeneratedStudentCode() {
  if (!newStudentCodeInput) return;
  const nom = String(newStudentNameInput?.value || "").trim();
  const telephone = String(newStudentPhoneInput?.value || "").trim();
  newStudentCodeInput.value = generateUniqueAccessCode(nom, telephone);
}

async function createStudentFromAdmin() {
  const nom = String(newStudentNameInput?.value || "").trim().toUpperCase();
  const telephone = String(newStudentPhoneInput?.value || "").trim();
  const code = generateUniqueAccessCode(nom, telephone);

  if (!nom || !telephone || !code) {
    setCreateStudentMessage("Saisis le nom complet et un numéro contenant au moins trois chiffres.", true);
    updateGeneratedStudentCode();
    return;
  }

  if (newStudentCodeInput) newStudentCodeInput.value = code;

  const existing = await findStudentByAccessCode(code);
  if (existing) {
    setCreateStudentMessage("Ce code existe déjà. Un suffixe sera ajouté automatiquement.", true);
    return;
  }

  const student = { code, nom, nomPrenoms: nom, telephone, createdAtText: new Date().toLocaleString("fr-FR") };
  registerStudentInCurrentBrowser(student);

  const users = getUsers();
  if (!users[code]) users[code] = { history: [] };
  setUsers(users);

  await waitForFirebaseReady();
  if (window.quizDB && window.quizDB.isReady && window.quizDB.createStudent) {
    try {
      await window.quizDB.createStudent(student);
      registerStudentInCurrentBrowser(student);
    } catch (error) {
      console.error("Erreur creation etudiant Firebase", error);
      setCreateStudentMessage("Espace cree localement. Firebase n'a pas pu sauvegarder en ligne.", true);
      await loadAdminData();
      return;
    }
  }

  if (newStudentNameInput) newStudentNameInput.value = "";
  if (newStudentPhoneInput) newStudentPhoneInput.value = "";
  if (newStudentCodeInput) newStudentCodeInput.value = "";
  setCreateStudentMessage("Espace etudiant cree. L'etudiant peut se connecter avec son code.");
  await loadAdminData();
}

function openAdminLogin() {
  hideAllCards();
  adminLoginCard.classList.remove("hidden");
  adminPasswordInput.value = "";
  adminLoginMessage.textContent = "";
}

async function openAdminDashboard() {
  if (adminPasswordInput.value !== ADMIN_PASSWORD) {
    adminLoginMessage.textContent = "Mot de passe admin incorrect.";
    adminLoginMessage.style.color = "#dc2626";
    return;
  }
  hideAllCards();
  adminCard.classList.remove("hidden");
  await loadAdminData();
}

function closeAdminDashboard() {
  hideAllCards();
  if (currentUser) {
    showStudentArea(currentUser);
  } else {
    location.replace("index.html");
  }
}


function mergeRowsBySignature(primaryRows, extraRows, signatureFn) {
  const seen = new Set();
  const merged = [];
  [...(primaryRows || []), ...(extraRows || [])].forEach((row) => {
    const signature = signatureFn(row);
    if (seen.has(signature)) return;
    seen.add(signature);
    merged.push(row);
  });
  return merged;
}

async function loadAdminData() {
  let results = [];
  let connections = [];

  await syncPendingFirebaseData();
  await waitForFirebaseReady();

  if (window.quizDB && window.quizDB.isReady) {
    try {
      results = await window.quizDB.getAllResults();
      connections = await window.quizDB.getConnections();
    } catch (error) {
      console.error("Erreur lecture admin Firebase", error);
    }
  }

  const localResults = [];
  const users = getUsers();
  Object.entries(users).forEach(([code, user]) => {
    (user.history || []).forEach((row) => localResults.push({ ...row, code }));
  });
  const pendingResults = JSON.parse(localStorage.getItem(PENDING_RESULTS_KEY) || "[]");
  const legacyAdminHistory = JSON.parse(localStorage.getItem("quiz_history") || "[]");
  results = mergeRowsBySignature(results, [...localResults, ...pendingResults, ...legacyAdminHistory], (row) => `${row.code || row.name || ""}|${row.date || row.createdAtText || ""}|${row.matiere || ""}|${row.sujet || ""}|${row.score ?? ""}|${row.mode || ""}`);

  const localConnections = JSON.parse(localStorage.getItem("quizPromoConnections") || "[]");
  const pendingConnections = JSON.parse(localStorage.getItem(PENDING_CONNECTIONS_KEY) || "[]");
  connections = mergeRowsBySignature(connections, [...localConnections, ...pendingConnections], (row) => `${row.code || ""}|${row.date || row.createdAtText || ""}|${row.action || ""}|${row.device || ""}`);

  results = results.map(normalizeResultRecord).filter((row) => row.code || row.nom || row.score !== null);
  connections = connections.map(normalizeConnectionRecord).filter((row) => row.code || row.nom || row.action);

  adminResultsCache = results;
  adminConnectionsCache = connections;
  await renderAdminTables(results, connections);
}

async function renderAdminTables(results, connections) {
  let students = await getAllStudentsFromList();

  // Si la liste ne sort pas, on reconstruit quand meme les etudiants depuis les notes/connexions.
  // Cela evite un tableau vide lorsque Firebase tarde ou lorsqu'un ancien navigateur n'a pas encore la liste locale.
  const studentMap = new Map();
  students.forEach((student) => {
    const normalized = normalizeStudentRecord(student);
    if (normalized.code) studentMap.set(normalized.code, normalized);
  });
  [...(results || []), ...(connections || [])].forEach((row) => {
    const code = normalizeStudentCode(row.code || row.name || row.matricule || row.studentCode);
    if (!code || studentMap.has(code)) return;
    studentMap.set(code, normalizeStudentRecord({
      code,
      nom: row.nom || row.nomPrenoms || row.studentName || getDisplayNameByAccessCode(code),
      telephone: row.telephone || row.numero || row.phone || row.tel || ""
    }));
  });
  students = Array.from(studentMap.values()).sort((a, b) => String(a.nom || '').localeCompare(String(b.nom || '')));

  const byCode = new Map();
  (results || []).forEach((row) => {
    const code = normalizeStudentCode(row.code || row.name || row.matricule || row.studentCode);
    if (!byCode.has(code)) byCode.set(code, []);
    byCode.get(code).push(row);
  });

  const connectionByCode = new Map();
  (connections || []).forEach((row) => {
    const code = normalizeStudentCode(row.code || row.name || row.matricule || row.studentCode);
    const previous = connectionByCode.get(code);
    if (!previous || parseHistoryDate(row.createdAtText || row.date) >= parseHistoryDate(previous.createdAtText || previous.date)) {
      connectionByCode.set(code, row);
    }
  });

  const scores = (results || []).map((row) => Number(row.score)).filter((score) => Number.isFinite(score));
  const avg = scores.length ? (scores.reduce((a, b) => a + b, 0) / scores.length).toFixed(2) : "0";
  if (adminStats) {
    adminStats.innerHTML = `
      <div class="stat-card"><strong>${students.length}</strong><span>Etudiants</span></div>
      <div class="stat-card"><strong>${(results || []).length}</strong><span>Notes enregistrees</span></div>
      <div class="stat-card"><strong>${avg}/20</strong><span>Moyenne generale</span></div>
      <div class="stat-card"><strong>${(connections || []).length}</strong><span>Connexions</span></div>
    `;
  }

  if (studentsTableBody) {
    if (!students.length) {
      studentsTableBody.innerHTML = `<tr><td colspan="6">Aucun etudiant defini trouve. Verifiez le fichier liste-acces.js ou creez un espace etudiant.</td></tr>`;
    } else {
      studentsTableBody.innerHTML = students.map((student) => {
        const rows = byCode.get(student.code) || [];
        const studentScores = rows.map((row) => Number(row.score)).filter((score) => Number.isFinite(score));
        const moyenne = studentScores.length ? (studentScores.reduce((a, b) => a + b, 0) / studentScores.length).toFixed(2) : "-";
        const lastConnection = connectionByCode.get(student.code);
        return `<tr><td>${escapeHtml(student.code)}</td><td>${escapeHtml(student.nom || student.nomPrenoms || "-")}</td><td>${escapeHtml(student.telephone || "-")}</td><td>${rows.length}</td><td>${moyenne}</td><td>${escapeHtml(lastConnection?.createdAtText || lastConnection?.date || "-")}</td></tr>`;
      }).join("");
    }
  }

  if (resultsTableBody) {
    resultsTableBody.innerHTML = (results || []).map((row) => `<tr>
      <td>${escapeHtml(row.createdAtText || row.date || "")}</td>
      <td>${escapeHtml(row.code || "")}</td>
      <td>${escapeHtml(row.nom || "")}</td>
      <td>${escapeHtml(row.matiere || row.subject || "-")}</td>
      <td>${escapeHtml(formatSubjectTitle(row.sujet || row.topic || "-"))}</td>
      <td>${row.score !== undefined && row.score !== null ? escapeHtml(row.score) + "/20" : "-"}</td>
      <td>${escapeHtml(row.mode || "-")}</td>
    </tr>`).join("");
  }

  if (connectionsTableBody) {
    connectionsTableBody.innerHTML = (connections || []).map((row) => `<tr>
      <td>${escapeHtml(row.createdAtText || row.date || "")}</td>
      <td>${escapeHtml(row.code || "")}</td>
      <td>${escapeHtml(row.nom || "")}</td>
      <td>${escapeHtml(row.device || "")}</td>
      <td>${escapeHtml(row.action || "")}</td>
    </tr>`).join("");
  }

  if (studentFullHistoryTableBody) {
    renderStudentFullHistoryTable(students, results || [], connections || []);
  }
  renderAdminHistory(results || [], connections || [], students);
}

function getHistoryDayKey(value) {
  const time = parseHistoryDate(value);
  if (time) {
    const d = new Date(time);
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, "0");
    const day = String(d.getDate()).padStart(2, "0");
    return `${y}-${m}-${day}`;
  }
  const text = String(value || "");
  const match = text.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (match) return `${match[3]}-${String(match[2]).padStart(2, "0")}-${String(match[1]).padStart(2, "0")}`;
  return "sans-date";
}

function formatHistoryDayTitle(dayKey) {
  if (!dayKey || dayKey === "sans-date") return "Date non renseignee";
  const [year, month, day] = dayKey.split("-");
  return `${day}/${month}/${year}`;
}

function buildDayConnectionHistoryRows(students, results, connections) {
  const studentByCode = new Map();
  (students || []).forEach((student) => {
    const normalized = normalizeStudentRecord(student);
    if (normalized.code) studentByCode.set(normalized.code, normalized);
  });

  const rows = [];

  (connections || []).forEach((row) => {
    const code = normalizeHistoryCode(row.code || row.name || row.matricule || row.studentCode);
    if (!code) return;
    const dayKey = getHistoryDayKey(row.createdAtText || row.date);
    const student = studentByCode.get(code);
    rows.push({
      dayKey,
      date: row.createdAtText || row.date || "-",
      code,
      nom: row.nom || row.nomPrenoms || student?.nom || student?.nomPrenoms || getDisplayNameByAccessCode(code) || "-",
      telephone: row.telephone || student?.telephone || student?.numero || student?.phone || "-",
      type: row.action === "deconnexion" ? "Deconnexion" : "Connexion",
      details: `Action: ${row.action || "connexion"}`,
      score: "-",
      device: row.device || "-",
      sortValue: parseHistoryDate(row.createdAtText || row.date)
    });
  });

  (results || []).forEach((row) => {
    const code = normalizeHistoryCode(row.code || row.name || row.matricule || row.studentCode);
    if (!code) return;
    const dayKey = getHistoryDayKey(row.createdAtText || row.date);
    const student = studentByCode.get(code);
    rows.push({
      dayKey,
      date: row.createdAtText || row.date || "-",
      code,
      nom: row.nom || row.nomPrenoms || student?.nom || student?.nomPrenoms || getDisplayNameByAccessCode(code) || "-",
      telephone: row.telephone || student?.telephone || student?.numero || student?.phone || "-",
      type: "Note",
      details: [
        `Matiere: ${row.matiere || row.subject || "non renseignee"}`,
        `Sujet: ${row.sujet || row.topic || "non renseigne"}`,
        row.mode ? `Mode: ${row.mode}` : ""
      ].filter(Boolean).join(" | "),
      score: row.score !== undefined && row.score !== null ? `${row.score}/20` : "-",
      device: row.device || "-",
      sortValue: parseHistoryDate(row.createdAtText || row.date)
    });
  });

  const seen = new Set();
  const uniqueRows = rows.filter((row) => {
    const signature = [row.dayKey, row.date, row.code, row.type, row.details, row.score, row.device].join("|");
    if (seen.has(signature)) return false;
    seen.add(signature);
    return true;
  });

  uniqueRows.sort((a, b) => (b.sortValue || 0) - (a.sortValue || 0) || String(a.nom || a.code).localeCompare(String(b.nom || b.code)));
  return uniqueRows;
}

function renderStudentFullHistoryTable(students, results, connections) {
  const historyRows = buildDayConnectionHistoryRows(students, results, connections);

  studentFullHistoryTableBody.innerHTML = historyRows.map((row) => `<tr>
    <td>${escapeHtml(row.date)}</td>
    <td>${escapeHtml(row.code)}</td>
    <td>${escapeHtml(row.nom)}</td>
    <td>${escapeHtml(row.type)}</td>
    <td>${escapeHtml(row.details)}</td>
    <td>${escapeHtml(row.score)}</td>
    <td>${escapeHtml(row.device)}</td>
  </tr>`).join("") || `<tr><td colspan="7">Aucun etudiant connecte trouve pour le moment.</td></tr>`;
}

function parseHistoryDate(value) {
  if (!value) return 0;
  const parsed = Date.parse(value);
  if (!Number.isNaN(parsed)) return parsed;
  const match = String(value).match(/(\d{1,2})\/(\d{1,2})\/(\d{4})(?:[\s,]+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/);
  if (!match) return 0;
  const [, day, month, year, hour = "0", minute = "0", second = "0"] = match;
  return new Date(Number(year), Number(month) - 1, Number(day), Number(hour), Number(minute), Number(second)).getTime();
}

async function exportAdminExcel() {
  // Export CSV local, compatible avec Excel et fonctionnant sans Internet.
  const students = await getAllStudentsFromList();
  const date = new Date().toISOString().slice(0, 10);
  const rows = [];

  students.forEach((row) => rows.push({
    section: "Etudiants",
    date: row.createdAtText || row.date || "",
    code: row.code || "",
    nom: row.nom || row.nomPrenoms || row.name || "",
    telephone: row.telephone || row.numero || row.phone || "",
    matiere: "",
    sujet: "",
    score: "",
    mode: "",
    action: "",
    appareil: row.device || ""
  }));

  adminResultsCache.forEach((row) => rows.push({
    section: "Resultats",
    date: row.createdAtText || row.date || "",
    code: row.code || "",
    nom: row.nom || "",
    telephone: row.telephone || "",
    matiere: row.matiere || row.subject || "",
    sujet: row.sujet || row.topic || "",
    score: row.score !== undefined && row.score !== null ? `${row.score}/20` : "",
    mode: row.mode || "",
    action: "",
    appareil: row.device || ""
  }));

  adminConnectionsCache.forEach((row) => rows.push({
    section: "Connexions",
    date: row.createdAtText || row.date || "",
    code: row.code || "",
    nom: row.nom || "",
    telephone: row.telephone || "",
    matiere: "",
    sujet: "",
    score: "",
    mode: "",
    action: row.action || "connexion",
    appareil: row.device || ""
  }));

  const headers = ["Section", "Date", "Code", "Nom", "Telephone", "Matiere", "Sujet", "Score", "Mode", "Action", "Appareil"];
  const keys = ["section", "date", "code", "nom", "telephone", "matiere", "sujet", "score", "mode", "action", "appareil"];
  const csvCell = (value) => `"${String(value ?? "").replace(/"/g, '""')}"`;
  const content = [headers.map(csvCell).join(";"), ...rows.map((row) => keys.map((key) => csvCell(row[key])).join(";"))].join("\r\n");
  const blob = new Blob(["\ufeff", content], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `export-quiz-l3-${date}.csv`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function exportAdminPDF() {
  // Rapport imprimable local. Le navigateur permet de choisir « Enregistrer au format PDF ».
  const date = new Date().toISOString().slice(0, 10);
  const escapePrintHtml = (value) => String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");

  const bodyRows = adminResultsCache.map((row) => `
    <tr>
      <td>${escapePrintHtml(row.createdAtText || row.date || "")}</td>
      <td>${escapePrintHtml(row.code || "")}</td>
      <td>${escapePrintHtml(row.nom || "")}</td>
      <td>${escapePrintHtml(row.matiere || row.subject || "")}</td>
      <td>${escapePrintHtml(formatSubjectTitle(row.sujet || row.topic || ""))}</td>
      <td>${escapePrintHtml(row.score !== undefined && row.score !== null ? `${row.score}/20` : "")}</td>
      <td>${escapePrintHtml(row.mode || "")}</td>
    </tr>`).join("") || '<tr><td colspan="7">Aucun resultat enregistre.</td></tr>';

  const report = `<!doctype html>
  <html lang="fr"><head><meta charset="utf-8"><title>Rapport ${escapePrintHtml(PORTAL_TITLE)}</title>
  <style>
    @page{size:A4 landscape;margin:12mm}body{font-family:Arial,sans-serif;color:#111;margin:0}
    h1{font-size:20px;margin:0 0 4px}p{margin:0 0 14px;color:#555}
    table{width:100%;border-collapse:collapse;font-size:9px}th,td{border:1px solid #999;padding:5px;text-align:left;vertical-align:top}
    th{background:#eee}tr{break-inside:avoid}
  </style></head><body>
  <h1>${escapePrintHtml(PORTAL_TITLE)} — Rapport des résultats</h1>
  <p>Genere le ${escapePrintHtml(new Date().toLocaleString("fr-FR"))}</p>
  <table><thead><tr><th>Date</th><th>Code</th><th>Nom</th><th>Matiere</th><th>Sujet</th><th>Score</th><th>Mode</th></tr></thead>
  <tbody>${bodyRows}</tbody></table>
  <script>window.addEventListener('load',()=>setTimeout(()=>window.print(),150));<\/script>
  </body></html>`;

  const printWindow = window.open("", "_blank");
  if (!printWindow) {
    alert("Autorisez l'ouverture de la fenetre d'impression, puis recommencez.");
    return;
  }
  printWindow.document.open();
  printWindow.document.write(report);
  printWindow.document.close();
}


