async function clearAllAdminData() {
  const ok = window.confirm("Voulez-vous vraiment effacer toutes les notes, historiques, connexions et classements ? Les espaces etudiants definis seront conserves.");
  if (!ok) return;

  if (clearAllDataBtn) {
    clearAllDataBtn.disabled = true;
    clearAllDataBtn.textContent = "Effacement...";
  }

  try {
    [LEADERBOARD_KEY, "quiz_history", "quizPromoConnections", PENDING_RESULTS_KEY, PENDING_CONNECTIONS_KEY, ADMIN_CACHE_KEY].forEach((key) => localStorage.removeItem(key));

    const users = getUsers();
    Object.keys(users).forEach((code) => {
      users[code].history = [];
    });
    setUsers(users);

    adminResultsCache = [];
    adminConnectionsCache = [];

    if (window.quizDB && window.quizDB.isReady && typeof window.quizDB.clearAllData === "function") {
      try {
        await window.quizDB.clearAllData();
      } catch (error) {
        console.error("Erreur suppression Firebase", error);
        alert("Les donnees locales ont ete effacees, mais la suppression en ligne a echoue. Verifiez la connexion internet puis reessayez.");
      }
    }

    await loadAdminData();
    alert("Les donnees ont ete effacees. Les espaces etudiants definis sont conserves.");
  } finally {
    if (clearAllDataBtn) {
      clearAllDataBtn.disabled = false;
      clearAllDataBtn.textContent = "Effacer toutes les donnees";
    }
  }
}

