// ===== Historique admin dans la partie etudiants definis =====
function normalizeHistoryCode(value) {
  return String(value || "").trim().toUpperCase();
}

function saveQuizHistory(entry) {
  try {
    const oldData = JSON.parse(localStorage.getItem("quiz_history") || "[]");
    const code = normalizeHistoryCode(entry.code || entry.name || currentUser || "");
    const nowText = new Date().toLocaleString("fr-FR");
    const normalizedEntry = {
      ...entry,
      code,
      nom: entry.nom || currentUserName || getDisplayNameByAccessCode(code),
      date: entry.createdAtText || entry.date || nowText,
      createdAtText: entry.createdAtText || entry.date || nowText,
      type: entry.type || selectedMode || "quiz",
      matiere: entry.matiere || selectedSubjectName || "",
      sujet: formatSubjectTitle(entry.sujet || selectedTopicName),
      mode: entry.mode || (lastAutoSubmitReason ? "automatique" : "manuel"),
      reason: entry.reason || lastAutoSubmitReason || "",
      device: entry.device || getDeviceLabel()
    };
    const signature = `${normalizedEntry.code}|${normalizedEntry.createdAtText || normalizedEntry.date}|${normalizedEntry.matiere || ""}|${normalizedEntry.sujet || ""}|${normalizedEntry.score ?? ""}|${normalizedEntry.mode || ""}`;
    const filtered = oldData.filter((row) => `${normalizeHistoryCode(row.code || row.name)}|${row.createdAtText || row.date || ""}|${row.matiere || ""}|${row.sujet || ""}|${row.score ?? ""}|${row.mode || ""}` !== signature);
    filtered.unshift(normalizedEntry);
    localStorage.setItem("quiz_history", JSON.stringify(filtered.slice(0, 1000)));
  } catch (e) {
    console.error("Erreur sauvegarde historique admin local", e);
  }
}

function buildFullHistoryRows(students, results, connections) {
  const studentByCode = new Map();
  (students || []).forEach((student) => {
    const code = normalizeHistoryCode(student.code);
    if (code) studentByCode.set(code, student);
  });

  const rows = [];
  (results || []).forEach((row) => {
    const code = normalizeHistoryCode(row.code || row.name);
    const student = studentByCode.get(code);
    rows.push({
      date: row.createdAtText || row.date || "-",
      code,
      nom: row.nom || student?.nom || getDisplayNameByAccessCode(code) || "-",
      type: "Note / Resultat",
      details: [
        `Matiere: ${row.matiere || row.subject || "non renseignee"}`,
        `Sujet: ${row.sujet || row.topic || "non renseigne"}`,
        `Mode: ${row.mode || "-"}`,
        row.type ? `Type: ${row.type}` : "",
        row.reason ? `Raison: ${row.reason}` : ""
      ].filter(Boolean).join(" | "),
      score: row.score !== undefined && row.score !== null ? `${row.score}/20` : "-",
      device: row.device || "-",
      sortValue: parseHistoryDate(row.createdAtText || row.date)
    });
  });

  (connections || []).forEach((row) => {
    const code = normalizeHistoryCode(row.code || row.name);
    const student = studentByCode.get(code);
    rows.push({
      date: row.createdAtText || row.date || "-",
      code,
      nom: row.nom || student?.nom || getDisplayNameByAccessCode(code) || "-",
      type: "Connexion",
      details: `Action: ${row.action || "connexion"}`,
      score: "-",
      device: row.device || "-",
      sortValue: parseHistoryDate(row.createdAtText || row.date)
    });
  });

  const hasHistoryByCode = new Set(rows.map((row) => normalizeHistoryCode(row.code)).filter(Boolean));
  (students || []).forEach((student) => {
    const code = normalizeHistoryCode(student.code);
    if (!code || hasHistoryByCode.has(code)) return;
    rows.push({
      date: student.createdAtText || student.date || "-",
      code,
      nom: student.nom || student.nomPrenoms || getDisplayNameByAccessCode(code) || "-",
      type: "Aucun historique",
      details: "Etudiant defini, mais aucune connexion ou note n'est encore enregistree.",
      score: "-",
      device: "-",
      sortValue: 0,
      emptyHistory: true
    });
  });

  rows.sort((a, b) => {
    if (a.emptyHistory && !b.emptyHistory) return 1;
    if (!a.emptyHistory && b.emptyHistory) return -1;
    return (b.sortValue || 0) - (a.sortValue || 0) || String(a.nom || a.code).localeCompare(String(b.nom || b.code));
  });
  return rows;
}

function renderAdminHistory(rows, connectionsRows, studentsRows) {
  const historyContainer = document.getElementById("admin-history-list");
  if (!historyContainer) return;

  const students = Array.isArray(studentsRows) && studentsRows.length
    ? studentsRows.map(normalizeStudentRecord).filter((student) => student.code)
    : getAllStudentsLocalOnly();
  const savedLocalHistory = JSON.parse(localStorage.getItem("quiz_history") || "[]");
  const results = Array.isArray(rows) ? rows : savedLocalHistory;
  const connections = Array.isArray(connectionsRows) ? connectionsRows : JSON.parse(localStorage.getItem("quizPromoConnections") || "[]");
  const fullRows = buildDayConnectionHistoryRows(students, results, connections);

  if (!fullRows.length) {
    historyContainer.innerHTML = '<p class="muted">Aucune connexion trouvee. Quand un etudiant se connecte, son historique apparaitra ici par jour.</p>';
    return;
  }

  const byDay = new Map();
  fullRows.forEach((row) => {
    if (!byDay.has(row.dayKey)) byDay.set(row.dayKey, []);
    byDay.get(row.dayKey).push(row);
  });

  const dayKeys = Array.from(byDay.keys()).sort((a, b) => {
    const ta = a === "sans-date" ? 0 : new Date(a + "T00:00:00").getTime();
    const tb = b === "sans-date" ? 0 : new Date(b + "T00:00:00").getTime();
    return tb - ta;
  });

  historyContainer.innerHTML = dayKeys.map((dayKey) => {
    const dayRows = byDay.get(dayKey) || [];
    const connectedCodes = new Set(dayRows.filter((row) => row.type === "Connexion" || row.type === "Deconnexion").map((row) => row.code));
    const notes = dayRows.filter((row) => row.type === "Note");
    const byStudent = new Map();
    dayRows.forEach((row) => {
      if (!byStudent.has(row.code)) byStudent.set(row.code, []);
      byStudent.get(row.code).push(row);
    });

    return `
      <div class="history-day-card">
        <div class="history-day-head">
          <strong>${escapeHtml(formatHistoryDayTitle(dayKey))}</strong>
          <span>${connectedCodes.size} etudiant(s) connecte(s)</span>
          <span>${notes.length} note(s)</span>
        </div>
        ${Array.from(byStudent.entries()).map(([code, items]) => {
          const first = items[0] || {};
          const studentNotes = items.filter((item) => item.type === "Note");
          const scores = studentNotes.map((item) => Number(String(item.score).replace("/20", ""))).filter((n) => Number.isFinite(n));
          const moyenne = scores.length ? (scores.reduce((a, b) => a + b, 0) / scores.length).toFixed(2) + "/20" : "-";
          const lastConnexion = items.find((item) => item.type === "Connexion") || items.find((item) => item.type === "Deconnexion");
          return `
            <div class="history-student-card">
              <div class="history-student-head">
                <strong>${escapeHtml(first.nom || "Etudiant")}</strong>
                <span>Code : ${escapeHtml(code || "-")}</span>
                <span>Telephone : ${escapeHtml(first.telephone || "-")}</span>
                <span>Nb notes du jour : ${studentNotes.length}</span>
                <span>Moyenne du jour : ${escapeHtml(moyenne)}</span>
                <span>Derniere connexion du jour : ${escapeHtml(lastConnexion?.date || "-")}</span>
              </div>
              <div class="table-wrap mini-table-wrap">
                <table class="mini-history-table">
                  <thead><tr><th>Heure / Date</th><th>Type</th><th>Details</th><th>Score</th><th>Appareil</th></tr></thead>
                  <tbody>
                    ${items.map((item) => `<tr>
                      <td>${escapeHtml(item.date)}</td>
                      <td>${escapeHtml(item.type)}</td>
                      <td>${escapeHtml(item.details)}</td>
                      <td>${escapeHtml(item.score)}</td>
                      <td>${escapeHtml(item.device)}</td>
                    </tr>`).join("")}
                  </tbody>
                </table>
              </div>
            </div>
          `;
        }).join("")}
      </div>
    `;
  }).join("");
}

document.addEventListener("DOMContentLoaded", () => {
  renderAdminHistory();
});
